responses.body:
[
  {{#repeat 5}}
  {
    "placa": "{{faker 'helpers.replaceSymbols' options='???####'}}",
    "renavam": "{{faker 'string.numeric' length=11}}",
    "descricaoMarcaModelo": "{{faker 'helpers.arrayElement' array='["FIAT/PALIO","VW/GOL","GM/ONIX","FORD/KA","TOYOTA/COROLLA","HONDA/CIVIC"]'}}",
    "anoFabricacao": {{faker 'number.int' min=2010 max=2025}},
    "anoModelo": {{faker 'number.int' min=2010 max=2025}},
    "chassi": "{{faker 'string.alphanumeric' length=17 casing='upper'}}",
    "quantidadeTotalRestricoes": {{faker 'number.int' min=0 max=5}},
    "versao": "1.0.0"
  }{{#unless @last}},{{/unless}}
  {{/repeat}}
]

{
  "placa": "{{request.params.placa}}",
  "chassi": "{{faker 'string.alphanumeric' length=17 casing='upper'}}",
  "recalls": [
    {{#repeat 2}}
    {
      "codigoCampanha": "{{faker 'string.alphanumeric' length=8 casing='upper'}}",
      "descricaoCampanha": "{{faker 'helpers.arrayElement' array='["Substituição do airbag do motorista","Verificação do sistema de freios","Atualização do software de controle do motor","Substituição da bomba de combustível","Verificação do sistema elétrico"]'}}",
      "dataInicioCampanha": "{{faker 'date.past' years=1 format='YYYY-MM-DD'}}",
      "statusAtendimento": "{{faker 'helpers.arrayElement' array='["PENDENTE","ATENDIDO","EM_ANDAMENTO"]'}}",
      "dataAtendimento": {{#if (faker 'helpers.arrayElement' array='[true,false,false]')}}"{{faker 'date.past' months=3 format='YYYY-MM-DD'}}"{{else}}null{{/if}}
    }{{#unless @last}},{{/unless}}
    {{/repeat}}
  ]
}
